DO $patch$ DECLARE s text; BEGIN SELECT pg_get_functiondef('public.mcp_update_work_item(uuid,jsonb,boolean,text,text)'::regprocedure) INTO s; IF strpos(s,'IF jsonb_typeof(p_patch->k) IS DISTINCT FROM ''string'' THEN')=0 THEN RAISE EXCEPTION 'update validation anchor mismatch'; END IF; s:=replace(s,'IF jsonb_typeof(p_patch->k) IS DISTINCT FROM ''string'' THEN','IF jsonb_typeof(p_patch->k) IS DISTINCT FROM ''string'' AND NOT (k=''authority_email'' AND p_patch->k=''null''::jsonb) THEN'); EXECUTE s; END $patch$;
COMMENT ON FUNCTION public.mcp_update_work_item(uuid,jsonb,boolean,text,text) IS 'Atomic owner/manage audited metadata and monitoring update; explicit JSON null clears obsolete authority_email, no identity or routing change.';